INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7728185, 1272382, 83313, '<td valign="top">I''m always surprised that these cars haven''t lost their shapes after so many layers of paint have been applied over the decades.</td>', 'I''m always surprised that these cars haven''t lost their shapes after so many layers of paint have been applied over the decades.', '2022-08-19 21:24:22.000000', NULL, 1),
(7728198, 1272249, 125275, '<td valign="top">This is great. It makes me take a moment and pause and reflect. The image is still and calm, but we know there was previously activity and movement, and the driveway tends towards recognizing there will be more movement, but for now it just is. The moment is silent and calm and anticipatory and full. It is liminal.</td>', 'This is great. It makes me take a moment and pause and reflect. The image is still and calm, but we know there was previously activity and movement, and the driveway tends towards recognizing there will be more movement, but for now it just is. The moment is silent and calm and anticipatory and full. It is liminal.', '2022-08-20 01:10:01.000000', NULL, 1),
(7728288, 1272367, 637, '<td valign="top">Love the DOF and the little guy inhaling pollen.  Clever composition.</td>', 'Love the DOF and the little guy inhaling pollen.  Clever composition.', '2022-08-21 17:12:20.000000', NULL, 1),
(7728290, 1272268, 637, '<td valign="top">Love the interplay of light and shadow...  the water and the sky aall well exposed.  Maybe the cropping of the bike is a little off.</td>', 'Love the interplay of light and shadow...  the water and the sky aall well exposed.  Maybe the cropping of the bike is a little off.', '2022-08-21 17:13:31.000000', NULL, 1),
(7728292, 1272454, 637, '<td valign="top">I guess the dog is your subject, but there are so many other things that draw my eye.  An unremarkable image.</td>', 'I guess the dog is your subject, but there are so many other things that draw my eye.  An unremarkable image.', '2022-08-21 17:14:36.000000', NULL, 1),
(7728293, 1272357, 637, '<td valign="top">Yes, just a whole lot of trees,  and nothing that really grabs my interet.</td>', 'Yes, just a whole lot of trees,  and nothing that really grabs my interet.', '2022-08-21 17:15:10.000000', NULL, 1),
(7728294, 1272426, 637, '<td valign="top">Meets the challenge!  Love the perspective and the colors.  Wondering if you could have cropped in the top corner of the building</td>', 'Meets the challenge!  Love the perspective and the colors.  Wondering if you could have cropped in the top corner of the building', '2022-08-21 17:16:00.000000', NULL, 1),
(7728296, 1272191, 637, '<td valign="top">Troubled by the composition or perhaps the crop.   If the bridge is the subject I''d look for it to be more prominent.</td>', 'Troubled by the composition or perhaps the crop.   If the bridge is the subject I''d look for it to be more prominent.', '2022-08-21 17:19:46.000000', NULL, 1),
(7728300, 1272365, 637, '<td valign="top">Such a unique image.  Well-composed, yet i keep wishing the rest of the photo  was as interesting as the statue on the box.</td>', 'Such a unique image.  Well-composed, yet i keep wishing the rest of the photo  was as interesting as the statue on the box.', '2022-08-21 17:21:56.000000', NULL, 1),
(7728302, 1272448, 637, '<td valign="top">Cute!  Despite my general concern that almost anything can be construed as "your conrner of the world".<br/> <br/>You capture the action of the kitten munching... nice light and shadow on the plants.</td>', 'Cute!  Despite my general concern that almost anything can be construed as "your conrner of the world". You capture the action of the kitten munching... nice light and shadow on the plants.', '2022-08-21 17:36:12.000000', NULL, 1),
(7728304, 1272331, 637, '<td valign="top">I was fooled.  The picture in the picture is well framed with good geometry.</td>', 'I was fooled.  The picture in the picture is well framed with good geometry.', '2022-08-21 17:39:03.000000', NULL, 1),
(7728306, 1272444, 637, '<td valign="top">I''d like an image that contains a window or a mirror reflection to be more remarkable than this.</td>', 'I''d like an image that contains a window or a mirror reflection to be more remarkable than this.', '2022-08-21 17:40:39.000000', NULL, 1),
(7728308, 1272186, 637, '<td valign="top">Wonderful that your friend finds your corner such a satisfying perch!  Nice dof, well composed.</td>', 'Wonderful that your friend finds your corner such a satisfying perch!  Nice dof, well composed.', '2022-08-21 17:45:51.000000', NULL, 1),
(7728309, 1272382, 637, '<td valign="top">Not sure what this is, but it''s well composed and i love all the colors</td>', 'Not sure what this is, but it''s well composed and i love all the colors', '2022-08-21 17:46:22.000000', NULL, 1),
(7728310, 1272449, 637, '<td valign="top">Well-composed, one of my favorites of the challenge.</td>', 'Well-composed, one of my favorites of the challenge.', '2022-08-21 17:48:07.000000', NULL, 1),
(7728311, 1272450, 637, '<td valign="top">Such interesting geometry on the bridge and along the water.  The little boat in the background seals the deal for me!</td>', 'Such interesting geometry on the bridge and along the water.  The little boat in the background seals the deal for me!', '2022-08-21 17:49:11.000000', NULL, 1),
(7728312, 1272366, 637, '<td valign="top">Love the monochrome and the geometry of this scene.  But what am I supposed to look at?</td>', 'Love the monochrome and the geometry of this scene.  But what am I supposed to look at?', '2022-08-21 17:50:26.000000', NULL, 1),
(7728313, 1272257, 637, '<td valign="top">Well composed, nice capture.</td>', 'Well composed, nice capture.', '2022-08-21 17:51:30.000000', NULL, 1),
(7728314, 1272204, 637, '<td valign="top">The more I look at it the more i like it... the white and blue mix together so subtly.  And there is even some nice geometry!</td>', 'The more I look at it the more i like it... the white and blue mix together so subtly.  And there is even some nice geometry!', '2022-08-21 17:52:47.000000', NULL, 1),
(7728315, 1272233, 637, '<td valign="top">I know this corner, so I''m trying to warm up to this image, but the composition leaves me hungry.</td>', 'I know this corner, so I''m trying to warm up to this image, but the composition leaves me hungry.', '2022-08-21 18:00:22.000000', NULL, 1),
(7728316, 1272408, 637, '<td valign="top">I love it when "Corner of the World" photos feature a corner.  Colorful and well composed  but otherwise unremarkable.</td>', 'I love it when "Corner of the World" photos feature a corner.  Colorful and well composed  but otherwise unremarkable.', '2022-08-21 18:01:11.000000', NULL, 1),
(7728317, 1272378, 637, '<td valign="top">Yes its a corner.</td>', 'Yes its a corner.', '2022-08-21 18:01:21.000000', NULL, 1),
(7728318, 1272440, 637, '<td valign="top">Cute, with obligatory shoes/feet.  Mostly unremarkable.</td>', 'Cute, with obligatory shoes/feet.  Mostly unremarkable.', '2022-08-21 18:02:50.000000', NULL, 1),
(7728319, 1272435, 637, '<td valign="top">Nice twilight capture, yet the sky seems a little blown out.  Love the idea of a tent right at the edge of the water.</td>', 'Nice twilight capture, yet the sky seems a little blown out.  Love the idea of a tent right at the edge of the water.', '2022-08-21 18:08:59.000000', NULL, 1),
